import{_ as i,l,o as e,c as n,v as t,p as s,x as r,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"复制与日志传送","description":"","frontmatter":{"title":"复制与日志传送","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/replication-log.md","filePath":"cs/replication-log.md","lastUpdated":1789023840000}'),A={name:"cs/replication-log.md"};function c(h,a,_,B,m,u){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="复制与日志传送" tabindex="-1">复制与日志传送 <a class="header-anchor" href="#复制与日志传送" aria-label="Permalink to &quot;复制与日志传送&quot;">​</a></h1><div class="epigraph"><p>把 WAL 运到备库重放，备库得到同一串已提交历史；同步还是异步决定故障时丢多少提交。</p><footer>—— 据 Gray and Reuter 对复制；ARIES 日志作为运输对象；Bernstein 对照</footer></div><p><a href="/cs/two-pc">上一课</a>让多个资源管理器一起提交。本课不重做投票。缺口是同一数据库的<strong>副本</strong>：不是两个独立 RM 的原子，而是一份历史的拷贝。日志传送（物理重放）与逻辑复制（重放 SQL）是两条路。分片下一课切的是键空间，不是同一键的副本。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>2PC 留下「跨 RM」。高可用常常是：一个主库接受写，备库应用主库日志。同步复制：提交等备库落日志，持久更强、延迟更大；异步：提交先返回，主挂可能丢尾部。缺口是<strong>用 WAL 当复制管道</strong>，复用 ARIES 的 REDO 解释器。</p><p><span class="marginnote">副本不是快照隔离的读者集合自动扩展：只读备库的可见性仍要定义。脑裂（两个主）是故障切换的规格问题，本课只点名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>主库刷提交记录后（或同时）发送给备。备库 REDO 到同一 LSN，不开独立 UNDO 来自用户（备库通常不接受写）。逻辑复制解析日志为行变更，便于异构版本。冲突在多主时出现，本课默认单主。</p>',8)),(e(),s(E,null,{default:r(()=>[p(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRI%5B%22%E4%B8%BB%E5%BA%93%20WAL%22%5D%20--%3E%20SHIP%5B%22%E4%BC%A0%E9%80%81%E8%AE%B0%E5%BD%95%22%5D%0A%20%20SHIP%20--%3E%20STBY%5B%22%E5%A4%87%E5%BA%93%20REDO%22%5D%0A%20%20SYNC%5B%22%E5%90%8C%E6%AD%A5%22%5D%20--%3E%20DUR%5B%22%E6%8F%90%E4%BA%A4%E5%90%AB%E5%A4%87%E5%BA%93%E6%8C%81%E4%B9%85%22%5D%0A%20%20ASYNC%5B%22%E5%BC%82%E6%AD%A5%22%5D%20--%3E%20LAG%5B%22%E5%8F%AF%E8%83%BD%E4%B8%A2%E5%A4%B1%E5%B0%BE%E9%83%A8%E6%8F%90%E4%BA%A4%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>复制把 D（持久）从「一块盘」扩展到「另一台机器的日志」。它不自动给跨分片事务；那要 2PC 或放弃原子。读扩展：只读可以打备库，但滞后是隔离规格的一部分。安全课的 CIA 里，副本也是泄密面。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Paxos/Raft 插入主干当默认复制课。键空间切开、每片一份，下一课分片。</p><p>后课默认：副本共享同一逻辑历史。容量不够时切键。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>日志传送让备库重放主库历史。</li><li>同步与异步换的是延迟与丢失窗口。</li><li>分片直觉下一课。</li><li>出处：Gray and Reuter；Mohan et al. ARIES。</li></ul>',7))])}const S=i(A,[["render",c]]);export{D as __pageData,S as default};
